     1→package das
     2→
     3→import (
     4→	"context"
     5→	"fmt"
     6→
     7→	"github.com/OffchainLabs/prysm/v6/beacon-chain/db/filesystem"
     8→	"github.com/OffchainLabs/prysm/v6/beacon-chain/verification"
     9→	"github.com/OffchainLabs/prysm/v6/config/params"
    10→	"github.com/OffchainLabs/prysm/v6/consensus-types/blocks"
    11→	"github.com/OffchainLabs/prysm/v6/consensus-types/primitives"
    12→	"github.com/OffchainLabs/prysm/v6/runtime/logging"
    13→	"github.com/OffchainLabs/prysm/v6/runtime/version"
    14→	"github.com/OffchainLabs/prysm/v6/time/slots"
    15→	"github.com/pkg/errors"
    16→	log "github.com/sirupsen/logrus"
    17→)
    18→
    19→var (
    20→	errMixedRoots = errors.New("BlobSidecars must all be for the same block")
    21→)
    22→
    23→// LazilyPersistentStoreBlob is an implementation of AvailabilityStore to be used when batch syncing.
    24→// This implementation will hold any blobs passed to Persist until the IsDataAvailable is called for their
    25→// block, at which time they will undergo full verification and be saved to the disk.
    26→type LazilyPersistentStoreBlob struct {
    27→	store    *filesystem.BlobStorage
    28→	cache    *blobCache
    29→	verifier BlobBatchVerifier
    30→}
    31→
    32→var _ AvailabilityStore = &LazilyPersistentStoreBlob{}
    33→
    34→// BlobBatchVerifier enables LazyAvailabilityStore to manage the verification process
    35→// going from ROBlob->VerifiedROBlob, while avoiding the decision of which individual verifications
    36→// to run and in what order. Since LazilyPersistentStore always tries to verify and save blobs only when
    37→// they are all available, the interface takes a slice of blobs, enabling the implementation to optimize
    38→// batch verification.
    39→type BlobBatchVerifier interface {
    40→	VerifiedROBlobs(ctx context.Context, blk blocks.ROBlock, sc []blocks.ROBlob) ([]blocks.VerifiedROBlob, error)
    41→}
    42→
    43→// NewLazilyPersistentStore creates a new LazilyPersistentStore. This constructor should always be used
    44→// when creating a LazilyPersistentStore because it needs to initialize the cache under the hood.
    45→func NewLazilyPersistentStore(store *filesystem.BlobStorage, verifier BlobBatchVerifier) *LazilyPersistentStoreBlob {
    46→	return &LazilyPersistentStoreBlob{
    47→		store:    store,
    48→		cache:    newBlobCache(),
    49→		verifier: verifier,
    50→	}
    51→}
    52→
    53→// Persist adds blobs to the working blob cache. Blobs stored in this cache will be persisted
    54→// for at least as long as the node is running. Once IsDataAvailable succeeds, all blobs referenced
    55→// by the given block are guaranteed to be persisted for the remainder of the retention period.
    56→func (s *LazilyPersistentStoreBlob) Persist(current primitives.Slot, sidecars ...blocks.ROBlob) error {
    57→	if len(sidecars) == 0 {
    58→		return nil
    59→	}
    60→
    61→	if len(sidecars) > 1 {
    62→		firstRoot := sidecars[0].BlockRoot()
    63→		for _, sidecar := range sidecars[1:] {
    64→			if sidecar.BlockRoot() != firstRoot {
    65→				return errMixedRoots
    66→			}
    67→		}
    68→	}
    69→	if !params.WithinDAPeriod(slots.ToEpoch(sidecars[0].Slot()), slots.ToEpoch(current)) {
    70→		return nil
    71→	}
    72→	key := keyFromSidecar(sidecars[0])
    73→	entry := s.cache.ensure(key)
    74→	for _, blobSidecar := range sidecars {
    75→		if err := entry.stash(&blobSidecar); err != nil {
    76→			return err
    77→		}
    78→	}
    79→	return nil
    80→}
    81→
    82→// IsDataAvailable returns nil if all the commitments in the given block are persisted to the db and have been verified.
    83→// BlobSidecars already in the db are assumed to have been previously verified against the block.
    84→func (s *LazilyPersistentStoreBlob) IsDataAvailable(ctx context.Context, current primitives.Slot, b blocks.ROBlock) error {
    85→	blockCommitments, err := commitmentsToCheck(b, current)
    86→	if err != nil {
    87→		return errors.Wrapf(err, "could not check data availability for block %#x", b.Root())
    88→	}
    89→	// Return early for blocks that are pre-deneb or which do not have any commitments.
    90→	if len(blockCommitments) == 0 {
    91→		return nil
    92→	}
    93→
    94→	key := keyFromBlock(b)
    95→	entry := s.cache.ensure(key)
    96→	defer s.cache.delete(key)
    97→	root := b.Root()
    98→	entry.setDiskSummary(s.store.Summary(root))
    99→
   100→	// Verify we have all the expected sidecars, and fail fast if any are missing or inconsistent.
   101→	// We don't try to salvage problematic batches because this indicates a misbehaving peer and we'd rather
   102→	// ignore their response and decrease their peer score.
   103→	sidecars, err := entry.filter(root, blockCommitments, b.Block().Slot())
   104→	if err != nil {
   105→		return errors.Wrap(err, "incomplete BlobSidecar batch")
   106→	}
   107→	// Do thorough verifications of each BlobSidecar for the block.
   108→	// Same as above, we don't save BlobSidecars if there are any problems with the batch.
   109→	vscs, err := s.verifier.VerifiedROBlobs(ctx, b, sidecars)
   110→	if err != nil {
   111→		var me verification.VerificationMultiError
   112→		ok := errors.As(err, &me)
   113→		if ok {
   114→			fails := me.Failures()
   115→			lf := make(log.Fields, len(fails))
   116→			for i := range fails {
   117→				lf[fmt.Sprintf("fail_%d", i)] = fails[i].Error()
   118→			}
   119→			log.WithFields(lf).WithFields(logging.BlockFieldsFromBlob(sidecars[0])).
   120→				Debug("Invalid BlobSidecars received")
   121→		}
   122→		return errors.Wrapf(err, "invalid BlobSidecars received for block %#x", root)
   123→	}
   124→	// Ensure that each BlobSidecar is written to disk.
   125→	for i := range vscs {
   126→		if err := s.store.Save(vscs[i]); err != nil {
   127→			return errors.Wrapf(err, "failed to save BlobSidecar index %d for block %#x", vscs[i].Index, root)
   128→		}
   129→	}
   130→	// All BlobSidecars are persisted - da check succeeds.
   131→	return nil
   132→}
   133→
   134→func commitmentsToCheck(b blocks.ROBlock, current primitives.Slot) ([][]byte, error) {
   135→	if b.Version() < version.Deneb {
   136→		return nil, nil
   137→	}
   138→
   139→	// We are only required to check within MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUEST
   140→	if !params.WithinDAPeriod(slots.ToEpoch(b.Block().Slot()), slots.ToEpoch(current)) {
   141→		return nil, nil
   142→	}
   143→
   144→	kzgCommitments, err := b.Block().Body().BlobKzgCommitments()
   145→	if err != nil {
   146→		return nil, err
   147→	}
   148→
   149→	maxBlobCount := params.BeaconConfig().MaxBlobsPerBlock(b.Block().Slot())
   150→	if len(kzgCommitments) > maxBlobCount {
   151→		return nil, errIndexOutOfBounds
   152→	}
   153→
   154→	result := make([][]byte, len(kzgCommitments))
   155→	copy(result, kzgCommitments)
   156→
   157→	return result, nil
   158→}
