   144→// Returns true if the blob with the same slot, proposer index, and blob index has been seen before.
   145→func (s *Service) hasSeenBlobIndex(slot primitives.Slot, proposerIndex primitives.ValidatorIndex, index uint64) bool {
   146→	s.seenBlobLock.RLock()
   147→	defer s.seenBlobLock.RUnlock()
   148→	b := append(bytesutil.Bytes32(uint64(slot)), bytesutil.Bytes32(uint64(proposerIndex))...)
   149→	b = append(b, bytesutil.Bytes32(index)...)
   150→	_, seen := s.seenBlobCache.Get(string(b))
   151→	return seen
   152→}
   153→
   154→// Sets the blob with the same slot, proposer index, and blob index as seen.
   155→func (s *Service) setSeenBlobIndex(slot primitives.Slot, proposerIndex primitives.ValidatorIndex, index uint64) {
   156→	s.seenBlobLock.Lock()
   157→	defer s.seenBlobLock.Unlock()
   158→	b := append(bytesutil.Bytes32(uint64(slot)), bytesutil.Bytes32(uint64(proposerIndex))...)
   159→	b = append(b, bytesutil.Bytes32(index)...)
   160→	s.seenBlobCache.Add(string(b), true)
   161→}
   162→
   163→func blobFields(b blocks.ROBlob) logrus.Fields {
   164→	return logrus.Fields{
   165→		"slot":          b.Slot(),
   166→		"proposerIndex": b.ProposerIndex(),
   167→		"blockRoot":     fmt.Sprintf("%#x", b.BlockRoot()),
   168→		"kzgCommitment": fmt.Sprintf("%#x", b.KzgCommitment),
   169→		"index":         b.Index,
   170→	}
   171→}
   172→
   173→func computeSubnetForBlobSidecar(index uint64, slot primitives.Slot) uint64 {
   174→	subnetCount := params.BeaconConfig().BlobsidecarSubnetCount
   175→	if slots.ToEpoch(slot) >= params.BeaconConfig().ElectraForkEpoch {
   176→		subnetCount = params.BeaconConfig().BlobsidecarSubnetCountElectra
   177→	}
   178→	return index % subnetCount
   179→}
