    23→// LazilyPersistentStoreBlob is an implementation of AvailabilityStore to be used when batch syncing.
    24→// This implementation will hold any blobs passed to Persist until the IsDataAvailable is called for their
    25→// block, at which time they will undergo full verification and be saved to the disk.
    26→type LazilyPersistentStoreBlob struct {
    27→	store    *filesystem.BlobStorage
    28→	cache    *blobCache
    29→	verifier BlobBatchVerifier
    30→}
    31→
    32→var _ AvailabilityStore = &LazilyPersistentStoreBlob{}
    33→
    34→// BlobBatchVerifier enables LazyAvailabilityStore to manage the verification process
    35→// going from ROBlob->VerifiedROBlob, while avoiding the decision of which individual verifications
    36→// to run and in what order. Since LazilyPersistentStore always tries to verify and save blobs only when
    37→// they are all available, the interface takes a slice of blobs, enabling the implementation to optimize
    38→// batch verification.
    39→type BlobBatchVerifier interface {
    40→	VerifiedROBlobs(ctx context.Context, blk blocks.ROBlock, sc []blocks.ROBlob) ([]blocks.VerifiedROBlob, error)
    41→}
    42→
    43→// NewLazilyPersistentStore creates a new LazilyPersistentStore. This constructor should always be used
    44→// when creating a LazilyPersistentStore because it needs to initialize the cache under the hood.
    45→func NewLazilyPersistentStore(store *filesystem.BlobStorage, verifier BlobBatchVerifier) *LazilyPersistentStoreBlob {
    46→	return &LazilyPersistentStoreBlob{
    47→		store:    store,
    48→		cache:    newBlobCache(),
    49→		verifier: verifier,
    50→	}
    51→}
